#define main original_point_shadow_main
#include "test-filter-point-shadow.cpp"
#undef main
#include "filter-normalize-raster.hpp"
namespace NormalizeTest {
Bytes pixels(std::size_t w,std::size_t h){Bytes b(w*h*4);for(std::size_t p=0;p<w*h;p++){b[p*4]=20+p%201;b[p*4+1]=40+p%101;b[p*4+2]=80+p%71;b[p*4+3]=1;}return b;}
Bytes expected(const Bytes& in,std::size_t w,const FilterSelectionRegion&r){Bytes out(in.size(),0);int lo=255,hi=0;for(int y=r.y1;y<r.y2;y++)for(int x=r.x1;x<r.x2;x++){auto p=(y*w+x)*4;if(in[p+3])for(int c=0;c<3;c++){lo=std::min(lo,int(in[p+c]));hi=std::max(hi,int(in[p+c]));}}for(int y=r.y1;y<r.y2;y++)for(int x=r.x1;x<r.x2;x++){auto p=(y*w+x)*4;for(int c=0;c<3;c++)out[p+c]=hi==lo?in[p+c]:255*(in[p+c]-lo)/(hi-lo);out[p+3]=in[p+3];}return out;}
struct Trace{std::size_t width,full,crop,read=0,written=0,zero=0;FilterSelectionRegion region;std::atomic<bool>&cancel;std::shared_ptr<FilterProgress>progress;unsigned events=0,at=0,flushes=0;bool fail=false;FilterSelectionRegion* mutate=nullptr;
 Trace(std::size_t w,std::size_t h,FilterSelectionRegion r,std::atomic<bool>&c,std::shared_ptr<FilterProgress>p):width(w),full(w*h*4),crop(std::size_t(r.x2-r.x1)*(r.y2-r.y1)*4),region(r),cancel(c),progress(p){}
 void event(Operation op,std::uint64_t offset=0,std::size_t count=0,const std::uint8_t*bytes=nullptr){require(!cancel,"Normalize IO after cancel");FilterProgress::Snapshot state;require(progress->try_snapshot(state)&&state.value<1,"Normalize premature progress");
  if(op!=Operation::flush)require(count&&count<=16384&&count%4==0&&offset+count<=full,"Normalize unbounded IO");
  if(op==Operation::write&&zero<full){require(offset==zero&&std::all_of(bytes,bytes+count,[](std::uint8_t v){return v==0;}),"Normalize zero-fill");zero+=count;if(mutate){*mutate={true,false,0,0,0,0};mutate=nullptr;}}
  else if(op!=Operation::flush){require(zero==full&&crop,"Normalize bad crop order");auto&total=op==Operation::read?read:written;require(total<(op==Operation::read?crop*2:crop),"Normalize extra pass");auto pos=total%crop;auto cw=std::size_t(region.x2-region.x1);auto x=pos/4%cw,y=pos/4/cw;require(offset==((y+region.y1)*width+x+region.x1)*4&&count<=(cw-x)*4,"Normalize escaped ROI");if(op==Operation::write)require(read>=crop+written+count,"Normalize output before full scan/read");total+=count;}
  else{require(zero==full&&read==crop*2&&written==crop&&++flushes==1,"Normalize premature flush");}
  ++events;if(events==at){if(fail)throw StorageFailure();cancel=true;}
 }
};
class Observed final:public FilterRaster{FilterRaster&base;Trace&t;bool source;public:Observed(FilterRaster&b,Trace&a,bool s):base(b),t(a),source(s){}std::uint64_t size()const noexcept override{return base.size();}void read(std::uint64_t o,std::size_t n,std::uint8_t*p)override{require(source,"Normalize read output");t.event(Operation::read,o,n);base.read(o,n,p);}void write(std::uint64_t o,std::size_t n,const std::uint8_t*p)override{require(!source,"Normalize write source");t.event(Operation::write,o,n,p);base.write(o,n,p);}void flush()override{require(!source,"Normalize flush source");t.event(Operation::flush);base.flush();}};
Outcome audited(const Bytes&in,Bytes&out,Trace&t){auto result=Outcome::cancelled;bool ok=filter_native_vector(in,t.cancel,out,[&](FilterRaster&a,FilterRaster&b,std::atomic<bool>&stop,const FilterRasterFactory&){Observed src(a,t,true),dst(b,t,false);result=filter_normalize_shadow_raster(src,t.width,t.full/(t.width*4),t.region,stop,dst,t.progress);return result!=Outcome::cancelled;});return ok?result:Outcome::cancelled;}
void test(){unsigned scenes=0,faults=0;for(auto shape:{std::make_pair(1u,1u),std::make_pair(67u,66u),std::make_pair(8205u,3u)}){std::size_t w=shape.first,h=shape.second;auto in=pixels(w,h);for(auto r:{full_region(w,h),FilterSelectionRegion{true,true,0,0,int(w),1},FilterSelectionRegion{true,false,0,0,0,0}}){auto want=expected(in,w,r);std::atomic<bool>stop{false};Bytes out;require(filter_normalize_shadow_vector(in,w,h,r,stop,out)==(r.intersects?Outcome::shadow:Outcome::no_merge)&&out==want,"Normalize vector ROI");auto alias=in;require(filter_normalize_shadow_vector(alias,w,h,r,stop,alias)==(r.intersects?Outcome::shadow:Outcome::no_merge)&&alias==want,"Normalize alias vector");auto progress=std::make_shared<FilterProgress>();Trace t(w,h,r,stop,progress);TemporaryFilterRaster a(directory,in.size()),b(directory,in.size());a.write(0,in.size(),in.data());Observed src(a,t,true),dst(b,t,false);require(filter_normalize_shadow_raster(src,w,h,r,stop,dst,progress)==(r.intersects?Outcome::shadow:Outcome::no_merge),"Normalize spill outcome");Bytes actual(in.size()),saved(in.size());b.read(0,actual.size(),actual.data());a.read(0,saved.size(),saved.data());require(actual==want&&saved==in,"Normalize spill bytes/source");scenes++;
 if(w==8205)for(bool fail:{false,true})for(unsigned at=1;at<=t.events;at++){std::atomic<bool>c{false};auto p=std::make_shared<FilterProgress>();Trace f(w,h,r,c,p);f.fail=fail;f.at=at;Bytes output{17,29,43},old=output;auto run=[&]{return audited(in,output,f);};if(fail)rejects<StorageFailure>(run,"Normalize missed IO fault");else require(run()==Outcome::cancelled,"Normalize missed cancel");require(output==old,"Normalize partial publish");faults++;}
 }}
 {auto in=pixels(8,8);FilterSelectionRegion region{true,true,2,2,6,6};auto want=expected(in,8,region);std::atomic<bool>stop{false};auto p=std::make_shared<FilterProgress>();Trace t(8,8,region,stop,p);t.mutate=&region;Memory a(in),b(in.size());Observed src(a,t,true),dst(b,t,false);require(filter_normalize_shadow_raster(src,8,8,region,stop,dst,p)==Outcome::shadow&&b.data==want&&!region.intersects,"Normalize mutable region snapshot");scenes++;}
 for(bool all_transparent:{false,true}){Bytes in{20,30,40,1,10,30,40,0};if(all_transparent)in[3]=0;Bytes out{1,2,3},old=out;std::atomic<bool>stop{false};rejects<std::domain_error>([&]{filter_normalize_shadow_vector(in,2,1,full_region(2,1),stop,out);},"Normalize undefined admission");require(out==old,"Normalize undefined published zeros");scenes++;}
 {std::atomic<bool>stop{true};Sized a(UINT64_C(46341)*46341*4),b(a.size());auto r=full_region(46341,46341);rejects<std::invalid_argument>([&]{filter_normalize_shadow_raster(a,46341,46341,r,stop,b);},"Normalize area overflow");require(a.calls==0&&b.calls==0,"Normalize invalid area IO");Sized c(std::uint64_t(INT32_MAX)*4),d(c.size());require(filter_normalize_shadow_raster(c,INT32_MAX,1,full_region(INT32_MAX,1),stop,d)==Outcome::cancelled&&c.calls==0&&d.calls==0,"Normalize valid large area preflight");scenes++;}
 std::cout<<"Normalize "<<scenes<<" ROI/vector/alias/spill/snapshot/domain scenes; "<<faults<<" two-pass/zero-fill/flush fault points preserve publication\n";
}
}
int main(int argc,char**argv){GError*error=nullptr;char*path=g_dir_make_tmp("normalize-shadow-XXXXXX",&error);require(path&&!error,"Normalize temporary directory");directory=path;g_free(path);try{NormalizeTest::test();}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}require(g_rmdir(directory.c_str())==0,"Normalize spill cleanup");return original_point_shadow_main(argc,argv);}
